export type getTreeResponse200 = {
  data: TreeOutput;
  status: 200;
};

export type getTreeResponseSuccess = getTreeResponse200 & {
  headers: Headers;
};
export type getTreeResponse = getTreeResponseSuccess;

export const getGetTreeUrl = () => {
  return `/trees`;
};

export const getTree = async (
  options?: RequestInit,
): Promise<getTreeResponse> => {
  const res = await fetch(getGetTreeUrl(), {
    ...options,
    method: 'GET',
  });

  const contentType = (res.headers.get('content-type') ?? '').toLowerCase();
  const body = [204, 205, 304].includes(res.status) ? null : await res.text();

  const parsedBody = body
    ? contentType.includes('json')
      ? JSON.parse(body)
      : body
    : {};
  const data = contentType.includes('json')
    ? orvalParseStandardSchema(Tree, parsedBody)
    : parsedBody;
  return { data, status: res.status, headers: res.headers } as getTreeResponse;
};

export const getGetTreeQueryKey = () => {
  return [`/trees`] as const;
};

export const getGetTreeQueryOptions = <
  TData = Awaited<ReturnType<typeof getTree>>,
  TError = unknown,
>(options?: {
  query?: Partial<
    UseQueryOptions<Awaited<ReturnType<typeof getTree>>, TError, TData>
  >;
  fetch?: RequestInit;
}) => {
  const { query: queryOptions, fetch: fetchOptions } = options ?? {};

  const queryKey = queryOptions?.queryKey ?? getGetTreeQueryKey();

  const queryFn: QueryFunction<Awaited<ReturnType<typeof getTree>>> = ({
    signal,
  }) => getTree({ signal, ...fetchOptions });

  return { queryKey, queryFn, ...queryOptions } as UseQueryOptions<
    Awaited<ReturnType<typeof getTree>>,
    TError,
    TData
  > & { queryKey: DataTag<QueryKey, TData, TError> };
};

